func TestBuildMemoryTagIndex(t *testing.T) {
	type sample struct {
		Top bool
		DB  struct {
			Inner int16
		}
		hidden bool
	}

	tags := buildMemoryTagIndex(reflect.TypeOf(sample{}))
	if len(tags) < 2 {
		t.Fatalf("buildMemoryTagIndex() len=%d, want >=2", len(tags))
	}
	var hasInner bool
	var hasTop bool
	for _, tag := range tags {
		if tag.Name == "DB.Inner" {
			hasInner = true
		}
		if tag.Name == "Top" {
			hasTop = true
		}
	}
	if !hasInner || !hasTop {
		t.Fatalf("missing expected tags in %+v", tags)
	}
}

func TestTUISearchRendering(t *testing.T) {
	m := model{
		tags:   []memoryTag{{Name: "DB_Main.Counter"}, {Name: "System.Flag"}},
		values: []string{"1", "true"},
		height: 20,
		width:  80,
	}
	m.applyFilter()
	m.query = "db"
	m.applyFilter()
	view := m.View()
	if !strings.Contains(strings.ToLower(view), "db_main.counter") {
		t.Fatalf("view missing filtered tag: %q", view)
	}
	if strings.Contains(strings.ToLower(view), "system.flag") {
		t.Fatalf("view still contains non-matching tag: %q", view)
	}
}

