func findWritableScalarTag(memType reflect.Type, tags []memoryTag) (memoryTag, any, any, any, bool) {
	for _, tag := range tags {
		if len(tag.Index) == 0 {
			continue
		}
		field := memType.FieldByIndex(tag.Index)
		switch field.Type.Kind() {
		case reflect.Bool:
			return tag, true, "bad", nil, true
		case reflect.Int8:
			return tag, int8(7), "bad", int16(1000), true
		case reflect.Int16:
			return tag, int16(7), "bad", int32(40000), true
		case reflect.Int32:
			return tag, int32(7), "bad", int64(1 << 40), true
		case reflect.Int, reflect.Int64:
			return tag, reflect.ValueOf(int64(7)).Convert(field.Type).Interface(), "bad", nil, true
		case reflect.Uint8:
			return tag, uint8(7), "bad", int16(-1), true
		case reflect.Uint16:
			return tag, uint16(7), "bad", int32(-1), true
		case reflect.Uint32:
			return tag, uint32(7), "bad", int64(-1), true
		case reflect.Uint, reflect.Uint64, reflect.Uintptr:
			return tag, reflect.ValueOf(uint64(7)).Convert(field.Type).Interface(), "bad", int16(-1), true
		case reflect.Float32:
			return tag, float32(7.5), "bad", nil, true
		case reflect.Float64:
			return tag, float64(7.5), "bad", nil, true
		case reflect.String:
			return tag, "written", int16(7), nil, true
		}
	}
	return memoryTag{}, nil, nil, nil, false
}

func dialOPCUATestClient(ctx context.Context, endpoint string) (*client.Client, error) {
	var lastErr error
	for attempt := 0; attempt < 20; attempt++ {
		ch, err := client.Dial(ctx, endpoint, client.WithInsecureSkipVerify())
		if err == nil {
			return ch, nil
		}
		lastErr = err
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(100 * time.Millisecond):
		}
	}
	return nil, fmt.Errorf("dial OPC-UA endpoint %s failed: %w", endpoint, lastErr)
}

func freeTCPPort(t *testing.T) int {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("net.Listen() error: %v", err)
	}
	defer ln.Close()
	addr, ok := ln.Addr().(*net.TCPAddr)
	if !ok {
		t.Fatalf("unexpected listener address type %T", ln.Addr())
	}
	return addr.Port
}
